import java.io.IOException;
import java.io.InputStreamReader;
import java.util.stream.Collectors;

@Configuration
public class QueryConfig {

    @Value("classpath:query.sql")
    private Resource sqlQueryResource;

    private String sqlQuery;

    @PostConstruct
    public void init() {
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(sqlQueryResource.getInputStream()))) {
            sqlQuery = reader.lines().collect(Collectors.joining("\n"));
        } catch (IOException e) {
            throw new RuntimeException("Error reading SQL query from file", e);
        }
    }

    public String getSqlQuery() {
        return sqlQuery;
    }
}
